// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address caller, uint256 value) public {
        vm.assume(caller != address(0));
        value = bound(value, 0, 1 ether);

        vm.deal(address(this), 1 ether);
        (bool sent, ) = address(c).call{value: 1 ether}('');
        require(sent, "funding failed");

        uint256 before = address(c).balance;
        vm.prank(address(this));
        bool ok;
        try c.sendMoney(caller, value) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
